<?php require dirname(__DIR__).'/config.php';admin_required();$pdo=db();$customers=$pdo->query("SELECT customer_name,phone,MAX(created_at) last_order,COUNT(*) orders_count,SUM(CASE WHEN status!='Cancelled' THEN total ELSE 0 END) spend FROM orders GROUP BY phone,customer_name ORDER BY last_order DESC")->fetchAll();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers — Aastha Admin</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="admin-shell"><aside class="sidebar"><a class="admin-brand" href="index.php"><span>A</span><b>Aastha<small>ADMIN PANEL</small></b></a><div class="side-label">MAIN MENU</div><a class="side-link" href="index.php"><i>▦</i> Dashboard</a><a class="side-link" href="orders.php"><i>☷</i> Orders</a><a class="side-link" href="products.php"><i>▣</i> Products</a><a class="side-link" href="categories.php"><i>▤</i> Categories</a><a class="side-link active" href="customers.php"><i>♙</i> Customers</a><a class="side-link" href="settings.php"><i>⚙</i> Store settings</a><div class="side-bottom"><a class="side-link" href="../index.php"><i>↗</i> View storefront</a><a class="side-link" href="logout.php"><i>⇥</i> Logout</a></div></aside><main class="admin-main"><header class="admin-topbar"><button class="mobile-menu" data-menu>☰</button><div class="crumb">Home <span>›</span> Customers</div><div class="admin-user"><span class="avatar">A</span><?=e($_SESSION['admin_name']??'Admin')?> <a href="logout.php">Logout ↗</a></div></header><section class="admin-content"><div class="page-title-row"><div><h1>Customers</h1><p>Customers are listed from their order details.</p></div></div><section class="panel"><div class="panel-head"><h2>Customer list</h2><span class="muted"><?=count($customers)?> customers</span></div><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Phone</th><th>Total orders</th><th>Total order value</th><th>Last order</th></tr></thead><tbody><?php foreach($customers as $c): ?><tr><td><b><?=e($c['customer_name'])?></b></td><td><?=e($c['phone'])?></td><td><?=$c['orders_count']?></td><td><?=money((float)$c['spend'])?></td><td><?=e($c['last_order'])?></td></tr><?php endforeach; ?><?php if(!$customers): ?><tr><td colspan="5" class="empty-cell">No customer orders yet.</td></tr><?php endif; ?></tbody></table></div></section></section></main></div><script src="../assets/js/admin.js"></script></body></html>